WITH with_latest AS (SELECT s.id, s.name, s.country, s.segment, s.credit_limit, latest.session_country FROM customers s LEFT JOIN LATERAL (SELECT c.country AS session_country FROM sessions c WHERE c.customer_id = s.id AND c.started_at <= s.signup_date ORDER BY c.started_at DESC, c.id DESC LIMIT 1) latest ON TRUE) SELECT id, name, segment, credit_limit, session_country FROM with_latest ORDER BY segment DESC NULLS LAST
